import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080";tok=None;log=[]
def token():
    global tok
    r=urllib.request.Request(B+"/token",method="POST",data=b"")
    tok=json.load(urllib.request.urlopen(r))["token"]
def get(p):
    for i in range(200):
        if not tok: token()
        r=urllib.request.Request(B+p,headers={"Authorization":"Bearer "+tok})
        try: return json.load(urllib.request.urlopen(r))
        except urllib.error.HTTPError as e:
            log.append((p,e.code))
            if e.code==401: token()
            elif e.code==404 and p.startswith("/customers"): return None
            elif e.code==429: time.sleep(float(e.headers.get("Retry-After") or 1))
            else: time.sleep(0.5)
        except Exception as e: log.append((p,str(e)));time.sleep(0.5)
    raise SystemExit("fail "+p)
seen={};dups=0;path="/orders?page=1";pages=0
while path:
    d=get(path);pages+=1
    for o in d["items"]:
        if o["id"] in seen: dups+=1
        else: seen[o["id"]]=o
    path=d["next"]
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={k:0 for k in["north","south","east","west"]};n=0;odd=[]
for o in seen.values():
    if o["status"]!="shipped": continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: odd.append(("naive",o["placed_at"]));t=t.replace(tzinfo=timezone.utc)
    if not(lo<=t<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
    cu=cust[c]
    if cu is None: odd.append(("nocust",o["id"],c));continue
    num=o["amount_cents"]*(100-cu["discount_pct"])
    v=(num+50)//100
    reg[cu["region"]]+=v;n+=1
json.dump({"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg},open("/workspace/result.json","w"),indent=2)
from collections import Counter
print(pages,d["total_pages"],len(seen),Counter(c for _,c in log),odd[:10],len(odd))
print(Counter(o["status"] for o in seen.values()), set(type(o["amount_cents"]) for o in seen.values()))
print(set(o["placed_at"][19:] for o in seen.values()))
print(Counter((c or {}).get("discount_pct") for c in cust.values()))
EOF
python3 -I /tmp/work/r.py; cat /workspace/result.json

